import * as C from './core.js';
import {adminAudit} from './admin-operations.js';
import {requireSocialDemo,socialConfig,currentId,membership,profileOf,accountOf,receipt,assertTradable} from './social-core.js';
export const GUILD_ROLES={leader:'Líder',officer:'Oficial',member:'Membro'};
export function createGuild(state,name,tag,description,now=Date.now()){
 requireSocialDemo(state);const cfg=socialConfig(state),id=currentId(state);if(!cfg.guildEnabled)throw new Error('As guildas estão pausadas.');if(membership(state))throw new Error('Saia da guilda atual antes de criar outra.');name=String(name).trim();tag=String(tag).trim().toUpperCase();if(name.length<3||name.length>35||!/^[A-Z0-9]{2,5}$/.test(tag))throw new Error('Use nome de 3–35 caracteres e sigla de 2–5 letras/números.');if(state.social.guilds.some(g=>g.tag===tag))throw new Error('Esta sigla já está em uso.');
 if(cfg.guildCreateCost)C.transaction(state,'Criação de guilda','RC',-cfg.guildCreateCost);const guild={id:C.uuid(),name,tag,description:String(description||'').slice(0,300),inviteCode:'G-'+C.uuid().replaceAll('-','').slice(0,8).toUpperCase(),founderId:id,xp:0,level:1,members:[{userId:id,role:'leader',joinedAt:now,invitedBy:null}],milestones:{},createdAt:now};state.social.guilds.push(guild);state.profile.guildOnboardedAt ||= now;return guild;
}
export function joinGuild(state,guildId,inviterId=null,userId=currentId(state),now=Date.now()){
 requireSocialDemo(state);const cfg=socialConfig(state),g=state.social.guilds.find(g=>g.id===guildId);if(!cfg.guildEnabled||!g)throw new Error('Guilda indisponível.');if(membership(state,userId))throw new Error('Este piloto já pertence a uma guilda.');if(!profileOf(state,userId))throw new Error('Piloto não encontrado.');if(g.members.length>=cfg.guildCapacity)throw new Error('A guilda está cheia.');if(inviterId&&!g.members.some(m=>m.userId===inviterId))throw new Error('O indicador não pertence à guilda.');
 const joiningProfile=profileOf(state,userId),eligible=!cfg.guildInviteOncePerPilot||!joiningProfile.guildOnboardedAt,bonuses=[];let parent=inviterId,level=1;const seen=new Set([userId]);
 while(parent){if(seen.has(parent))throw new Error('Convite circular inválido.');seen.add(parent);const ancestor=g.members.find(m=>m.userId===parent);if(!ancestor)break;
  if(eligible&&level<=3){const key=cfg.guildInviteOncePerPilot?`guild-onboarding:${userId}:${level}`:`guild-invite:${g.id}:${userId}:${level}`,amount=cfg['guildInviteLevel'+level];if(!state.social.rewardReceipts.some(r=>r.key===key)){const account=accountOf(state,parent);if(!Number.isSafeInteger(account.balances.RC+amount))throw new Error('Saldo de bônus acima do limite.');bonuses.push({key,amount,parent,level});}}
  parent=ancestor.invitedBy;level++;
 }
 joiningProfile.guildOnboardedAt ||= now;const member={userId,role:'member',joinedAt:now,invitedBy:inviterId};g.members.push(member);
 for(const bonus of bonuses)receipt(state,bonus.key,'Bônus de convite à guilda · nível '+bonus.level,bonus.amount,bonus.parent,now);
 return member;
}
export function manageMember(state,guildId,userId,action){requireSocialDemo(state);const own=membership(state),g=state.social.guilds.find(g=>g.id===guildId),target=g?.members.find(m=>m.userId===userId);if(!own||own.guild.id!==guildId||!target)throw new Error('Membro não encontrado.');const actor=own.member;
 if(state.social.activeGuildBattle?.guildId===guildId&&userId===currentId(state))throw new Error('Termine o duelo antes de alterar sua participação.');
 if(action==='leave'){if(userId!==currentId(state))throw new Error('Use expulsar para outro membro.');if(actor.role==='leader'&&g.members.length>1)throw new Error('Transfira a liderança antes de sair.');g.members=g.members.filter(m=>m!==target);if(!g.members.length)state.social.guilds=state.social.guilds.filter(x=>x.id!==g.id);return;}
 if(action==='kick'){if(actor.role==='member'||target.role==='leader'||actor.role==='officer'&&target.role!=='member'||userId===currentId(state))throw new Error('Seu cargo não permite esta ação.');g.members=g.members.filter(m=>m!==target);return;}
 if(actor.role!=='leader'||userId===currentId(state))throw new Error('Só o líder pode alterar a hierarquia de outros membros.');
 if(action==='leader'){actor.role='officer';target.role='leader';}else if(['officer','member'].includes(action))target.role=action;else throw new Error('Cargo inválido.');
}
export function eventState(state,id,now=Date.now()){const event=state.social.eventSnapshots[id]||state.social.events.find(e=>e.id===id);if(!event)return null;return {...event,phase:event.enabled===false?'paused':now<event.startsAt?'upcoming':now>=event.endsAt?'ended':'active'};}
export function beginGuildBattle(state,eventId,uid,now=Date.now()){
 requireSocialDemo(state);const own=membership(state),cfg=socialConfig(state),event=eventState(state,eventId,now);if(!cfg.guildEnabled||!own)throw new Error('Entre em uma guilda para batalhar.');if(event?.phase!=='active')throw new Error('A guerra não está aberta.');if(state.social.activeGuildBattle)throw new Error('Termine o duelo em andamento.');const {r}=assertTradable(state,currentId(state),uid,now),player=C.robotInfo(state,r,now);if(!player.remainingBattles)throw new Error('Este robô esgotou seus usos.');
 const day=state.social.guildDaily[currentId(state)]||{date:C.dayKey(now),used:0};if(day.date!==C.dayKey(now)){day.date=C.dayKey(now);day.used=0;}if(day.used>=cfg.guildDailyBattles)throw new Error('Seus duelos de guilda de hoje acabaram.');
 const participants=state.social.warParticipantGuild?.[eventId]||{};if(participants[currentId(state)]&&participants[currentId(state)]!==own.guild.id)throw new Error('Você representa uma única guilda nesta edição.');
 const rivals=state.social.guilds.filter(g=>g.id!==own.guild.id&&g.members.length);if(!rivals.length)throw new Error('Nenhuma guilda adversária está disponível.');const rival=rivals[0],model=state.catalog.find(r=>r.id==='titan')||state.catalog[0],enemy={id:C.uuid(),name:rival.name,def:C.clone(model),health:Math.round(player.health*.9),attack:Math.round(player.attack*.9),defense:Math.round(player.defense*.85),boss:true};
 state.social.warParticipantGuild ||= {};state.social.warParticipantGuild[eventId] ||= {};state.social.warParticipantGuild[eventId][currentId(state)]=own.guild.id;
 state.social.eventSnapshots[eventId] ||= C.clone({...event,phase:undefined});state.social.guildDaily[currentId(state)]=day;day.used++;r.used++;
 const ticket={id:C.uuid(),kind:'guild',userId:currentId(state),uid,guildId:own.guild.id,rivalGuildId:rival.id,eventId,scene:event.scene,player:C.clone(player),enemies:[enemy],opponent:{...enemy,isBot:true},rules:C.combatRules(state),enemyIndex:0,defeated:0,playerHP:player.health,enemyHP:enemy.health,energy:0,round:1,turns:0,status:'fighting',settled:false,reward:event.battleRewardRC??cfg.guildBattleRewardRC,winPoints:cfg.guildWinPoints,lossPoints:cfg.guildLossPoints,xpPerPoint:cfg.guildXPPerPoint,levelRewardRC:cfg.guildLevelRewardRC,xpPerLevel:cfg.guildXPPerLevel,maxGuildLevel:cfg.guildMaxLevel,loss:0,deadlineAt:Math.min(event.endsAt,now+cfg.guildDuelTimeoutSeconds*1000),at:now};state.social.activeGuildBattle=ticket;return ticket;
}
export function settleGuildBattle(state,ticket,now=Date.now()){
 requireSocialDemo(state);if(ticket.userId!==currentId(state)||state.social.activeGuildBattle?.id!==ticket.id)throw new Error('Duelo não pertence ao piloto ou já foi encerrado.');if(ticket.settled||!['won','lost'].includes(ticket.status))throw new Error('O duelo não pode ser liquidado novamente.');const g=state.social.guilds.find(g=>g.id===ticket.guildId);if(!g)throw new Error('Guilda não encontrada.');if(now>=ticket.deadlineAt){ticket.status='lost';ticket.settled=true;state.social.activeGuildBattle=null;return {win:false,points:0,reward:0,level:g.level,expired:true};}const win=ticket.status==='won',points=win?ticket.winPoints:ticket.lossPoints;
 if(win)receipt(state,'guild-duel:'+ticket.id,'Vitória na guerra de guildas',ticket.reward,currentId(state),now);
 const board=state.social.warScores[ticket.eventId] ||= {};const score=board[g.id] ||= {points:0,participants:{}};score.points+=points;score.participants[currentId(state)]=(score.participants[currentId(state)]||0)+points;
 g.xp+=points*ticket.xpPerPoint;const nextLevel=Math.min(ticket.maxGuildLevel,1+Math.floor(g.xp/ticket.xpPerLevel));for(let level=g.level+1;level<=nextLevel;level++)g.milestones[level]={at:now,eligibleIds:g.members.map(m=>m.userId),rewardRC:ticket.levelRewardRC*level};g.level=Math.max(g.level,nextLevel);ticket.settled=true;state.social.activeGuildBattle=null;return {win,points,reward:win?ticket.reward:0,level:g.level};
}
export function claimGuildLevel(state,level,now=Date.now()){requireSocialDemo(state);const own=membership(state),milestone=own?.guild.milestones[level];if(!milestone||!milestone.eligibleIds.includes(currentId(state)))throw new Error('Você não participou deste marco de nível.');return receipt(state,`guild-level:${own.guild.id}:${level}:${currentId(state)}`,'Marco de nível da guilda',milestone.rewardRC,currentId(state),now);}
export function claimWarReward(state,id,now=Date.now()){requireSocialDemo(state);const guildId=state.social.warParticipantGuild?.[id]?.[currentId(state)],event=eventState(state,id,now),board=state.social.warScores[id]||{},score=board[guildId];if(event?.phase!=='ended'||!score||!Object.hasOwn(score.participants,currentId(state)))throw new Error('Aguarde o fim da guerra e participe com sua guilda.');const winner=Object.entries(board).sort((a,b)=>b[1].points-a[1].points||a[0].localeCompare(b[0]))[0]?.[0],count=Object.keys(score.participants).length,amount=event.participationRC+(winner===guildId?Math.floor(event.rewardPoolRC/count):0);return receipt(state,`guild-war:${id}:${currentId(state)}`,'Recompensa final de guerra',amount,currentId(state),now);}
export function saveGuildEvent(state,event){requireSocialDemo(state);if(!event.name?.trim()||!Number.isFinite(event.startsAt)||!Number.isFinite(event.endsAt)||event.endsAt<=event.startsAt||event.endsAt-event.startsAt>90*C.DAY||!['guild-canyon','guild-boreal'].includes(event.scene))throw new Error('Configure nome, mapa e período do evento.');for(const k of ['rewardPoolRC','participationRC','battleRewardRC'])if(!Number.isSafeInteger(event[k])||event[k]<0)throw new Error('Recompensas devem ser inteiras e não negativas.');if(state.social.eventSnapshots[event.id])throw new Error('Este evento já tem participação. Crie outra edição para mudar seu contrato.');const index=state.social.events.findIndex(e=>e.id===event.id),before=index>=0?C.clone(state.social.events[index]):null;if(index>=0)state.social.events[index]=C.clone(event);else state.social.events.push(C.clone(event));adminAudit(state,'guild_event',event.id,before,event,'Edição de evento salva no painel');}
